      SUBROUTINE SQUIRMCC     PARTIAL DERIVATIVES OF FLOOR COORDINATE TRANSFORMATIONSCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COCOM.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0C.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM7B.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM13A.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'ELM16A.CIN'      INCLUDE 'ELM20.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'INDBND.CIN'      INCLUDE 'OC.CIN'      INCLUDE 'OIV.CIN'      INCLUDE 'R.CIN'C      DO 50 J = 1, 3      XIV(J) = 0.0      DO 50 K = 1, 3      OIV(J,K) = 0.0   50 CONTINUEC      IF (TYPEC .EQ. 20) GO TO 2000      IF (TYPE .EQ. 2) GO TO 200      IF (TYPE .EQ. 3) GO TO 300      IF (TYPE .EQ. 4) GO TO 400      IF (TYPE .EQ. 5) GO TO 500      IF (TYPE .EQ. 13) GO TO 1300      IF (TYPE .EQ. 14) GO TO 1400      IF (TYPE .EQ. 16) GO TO 1600      IF (TYPE .EQ. 19) GO TO 1900      IF (TYPE .EQ. 28 .OR. TYPE .EQ. 29) GO TO 2800      IF (TYPE .EQ. 43) GO TO 4300      GO TO 5020CC     2. -- POLE FACE ROTATIONC  200 GO TO 5000CC     3. -- DRIFT SPACEC  300 XIV(3) = UNITI(8)      GO TO 5020CC     4. -- BENDING MAGNETC  400 IF (JV .GE. 5) GO TO 470      CALL DFBEND      IF (FLUSHL) GO TO 5020C  470 GO TO 5000CC     5. -- QUADRUPOLEC  500 IF (JV .NE. 1) GO TO 5000      XIV(3) = UNITI(8)      GO TO 5000CC     13. -- REALIGN BEAM LINE ALONG BEAM CENTROIDC 1300 XPR = COF(2)      YPR = COF(4)      WPXP = SQRT(1.0 + XPR**2)      WPXYP = SQRT(1.0 + XPR**2 + YPR**2)      DSTDXP = 1.0/WPXP**3      DCTDXP = - XPR/WPXP**3      DSPDXP = - XPR*YPR/WPXYP**3      DCPDXP = XPR*YPR**2/(WPXP*WPXYP**3)      DSPDYP = (1.0 + XPR**2)/WPXYP      DCPDYP = - YPR*WPXP/WPXYP**3      SINT = - O(1,1,3)      COST = O(1,1,1)      SINP = O(1,3,2)      COSP = O(1,2,2)      XIV(1) = COV(1,NV2)      XIV(2) = COV(3,NV2)      OIV(1,1) = DCTDXP*COV(2,NV2)      OIV(1,3) = - DSTDXP*COV(2,NV2)      OIV(2,1) = - (SINP*DSTDXP + DSPDXP*SINT)*COV(2,NV2)     1         - DSPDYP*COV(4,NV2)*SINT      OIV(2,2) = DCPDXP*COV(2,NV2) + DCPDYP*COV(4,NV2)      OIV(2,3) = - (COST*DSPDXP + DCTDXP*SINP)*COV(2,NV2)     1         - COST*DSPDYP*COV(4,NV2)      OIV(3,1) = (SINT*DCPDXP + DSTDXP*COSP)*COV(2,NV2)     1         + SINT*DCPDYP*COV(4,NV2)      OIV(3,2) = DSPDXP*COV(2,NV2) + DSPDYP*COV(4,NV2)      OIV(3,3) = (DCTDXP*COSP + COST*DCPDXP)*COV(2,NV2)     1         + COST*DCPDYP*COV(4,NV2)      GO TO 5000CC     14. -- ARIBTRARY MATRIXC 1400 GO TO 5020CC     16. -- SPECIAL PARAMETERSC 1600 J = NPARS      IF (JV .NE. 2) GO TO 5000      IF (J .GE. 16 .AND. J .LE. 18) GO TO 1610      IF (J .EQ. 19) GO TO 1620      IF (J .EQ. 20) GO TO 1630      GO TO 5020C 1610 XIV(J-15) = UFLOOR(1)      GO TO 5020C 1620 OIV(1,1) = - O(4,1,3)*UFLOOR(2)      OIV(3,3) = OIV(1,1)      OIV(1,3) = - O(4,1,1)*UFLOOR(2)      OIV(3,1) = - OIV(1,3)      GO TO 5020C 1630 OIV(2,2) = O(1,2,3)*UFLOOR(2)      OIV(2,3) = - O(1,2,2)*UFLOOR(2)      OIV(3,2) = - OIV(2,3)      OIV(3,3) = OIV(2,2)      GO TO 5020CC     19. -- SOLENOIDC 1900 IF (JV .NE. 1) GO TO 5000      XIV(3) = UNITI(8)      GO TO 5020CC     20. -- BEAM ROTATIONC 2000 IF (REFER) GO TO 5000      DTH = DPARM*UNITI(13)      IF (TYPE .NE. 20 .AND. .NOT. BEFORE) DTH = - DTH      DCS = - R(2,4)*DTH      IF (NDIF .LT. 0) DCS = - DCS      OIV(1,1) = DCS      OIV(2,2) = DCS      DSN = R(4,4)*DTH      IF (NDIF .LT. 0) DSN = - DSN      OIV(1,2) = DSN      OIV(2,1) = - DSN      GO TO 5020CC     28. -- RECTANGULAR BENDING MAGNETC 2800 IF (TYPEC .EQ. 2) GO TO 5020      IF (TYPEC .EQ. 20) GO TO 2820      CALL DFBEND      IF (FLUSHL) GO TO 5020      IF (JV .EQ. NTILT) GO TO 5020      GO TO 5000C 2820 GO TO 5020CC     43. -- COORDINATE SYSTEM SHIFTC 4300 CALL DSHFT      IF (JV .NE. 2 .AND. JV .NE. 4 .AND. JV .NE. 5 .AND. JV .NE. 6)     1    GO TO 5020      GO TO 5000CC     RETURNC 5000 IF (REFER .AND. TOTROT .NE. 0.0) CALL ROTATC(NV2) 5020 RETURN      END